PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE inventario (
  id        INTEGER PRIMARY KEY,
  ref       TEXT DEFAULT '',
  aula      TEXT DEFAULT '',
  mod       TEXT DEFAULT '',
  item      TEXT DEFAULT '',
  qty       INTEGER DEFAULT 0,
  min       INTEGER DEFAULT 0,
  cat       TEXT DEFAULT '',
  loc       TEXT DEFAULT '',
  est       TEXT DEFAULT '',
  util      TEXT DEFAULT '',
  fecha     TEXT DEFAULT '',
  mant      TEXT DEFAULT '',
  mantFecha TEXT DEFAULT '',
  mantNota  TEXT DEFAULT '',
  mantResp  TEXT DEFAULT '',
  mantEstado TEXT DEFAULT '',
  mantSolicitante TEXT DEFAULT '',
  mantSolicitanteEmail TEXT DEFAULT '',
  foto      TEXT DEFAULT '',
  obs       TEXT DEFAULT '',
  code      TEXT DEFAULT ''
, es_contenedor INTEGER DEFAULT 0, parent_id INTEGER DEFAULT NULL, tipo_material TEXT DEFAULT 'consumible', proveedor TEXT DEFAULT '', tags TEXT DEFAULT '', privado INTEGER DEFAULT 0, oculto INTEGER DEFAULT 0);
CREATE TABLE usuarios (
  usuario  TEXT PRIMARY KEY,
  password TEXT DEFAULT '',
  nombre   TEXT DEFAULT '',
  rol      TEXT DEFAULT 'profesor',
  email    TEXT DEFAULT ''
, privado INTEGER DEFAULT 0, google_id TEXT DEFAULT NULL, auth_method TEXT DEFAULT 'password', created_at DATETIME DEFAULT NULL, last_login DATETIME DEFAULT NULL, session_token TEXT DEFAULT NULL);
CREATE TABLE profesores (
  id           INTEGER PRIMARY KEY,
  nombre       TEXT DEFAULT '',
  departamento TEXT DEFAULT '',
  email        TEXT DEFAULT ''
);
CREATE TABLE prestamos (
  id               INTEGER PRIMARY KEY,
  itemId           INTEGER DEFAULT 0,
  itemNombre       TEXT DEFAULT '',
  cantidad         INTEGER DEFAULT 0,
  aulaOrigen       TEXT DEFAULT '',
  aulaDestino      TEXT DEFAULT '',
  profesorId       INTEGER DEFAULT 0,
  profesorNombre   TEXT DEFAULT '',
  gestionadoPor    TEXT DEFAULT '',
  fechaPrestamo    TEXT DEFAULT '',
  fechaPrevista    TEXT DEFAULT '',
  fechaDevolucion  TEXT DEFAULT '',
  cantidadDevuelta INTEGER DEFAULT 0,
  estado           TEXT DEFAULT 'activo',
  obs              TEXT DEFAULT ''
);
CREATE TABLE aulas (
  id    TEXT PRIMARY KEY,
  name  TEXT DEFAULT '',
  icon  TEXT DEFAULT '',
  desc  TEXT DEFAULT '',
  th    TEXT DEFAULT '',
  orden INTEGER DEFAULT 0
, privado INTEGER DEFAULT 0);
CREATE TABLE categorias (
  name  TEXT PRIMARY KEY,
  c     TEXT DEFAULT '',
  bg    TEXT DEFAULT '',
  i     TEXT DEFAULT '',
  orden INTEGER DEFAULT 0
, privado INTEGER DEFAULT 0);
CREATE TABLE ciclos (
  cicloId     TEXT,
  cicloNombre TEXT DEFAULT '',
  nivel       TEXT DEFAULT '',
  icon        TEXT DEFAULT '',
  th          TEXT DEFAULT '',
  desc        TEXT DEFAULT '',
  modCod      TEXT DEFAULT '',
  modNombre   TEXT DEFAULT '',
  modHoras    INTEGER DEFAULT 0,
  cicloOrden  INTEGER DEFAULT 0,
  modOrden    INTEGER DEFAULT 0, responsable TEXT DEFAULT '',
  PRIMARY KEY (cicloId, modCod)
);
CREATE TABLE modulos (
  cod         TEXT PRIMARY KEY,
  nombre      TEXT DEFAULT '',
  responsable TEXT DEFAULT ''
);
CREATE TABLE documentos (
  id         INTEGER PRIMARY KEY,
  itemId     INTEGER DEFAULT 0,
  itemNombre TEXT DEFAULT '',
  aulaId     TEXT DEFAULT '',
  fileName   TEXT DEFAULT '',
  driveId    TEXT DEFAULT '',
  driveUrl   TEXT DEFAULT '',
  fecha      TEXT DEFAULT ''
);
CREATE TABLE log (
  id      INTEGER PRIMARY KEY AUTOINCREMENT,
  fecha   TEXT DEFAULT '',
  usuario TEXT DEFAULT '',
  nombre  TEXT DEFAULT '',
  rol     TEXT DEFAULT '',
  accion  TEXT DEFAULT '',
  itemId  TEXT DEFAULT '',
  resumen TEXT DEFAULT ''
);
CREATE TABLE reset_tokens (
  token   TEXT PRIMARY KEY,
  usuario TEXT DEFAULT '',
  expires INTEGER DEFAULT 0
);
CREATE TABLE app_meta (key TEXT PRIMARY KEY, value TEXT DEFAULT '');
CREATE TABLE ubicaciones (name TEXT PRIMARY KEY, orden INTEGER DEFAULT 0);
CREATE TABLE intent_learning (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL,
  phrase_raw TEXT NOT NULL,
  phrase_norm TEXT NOT NULL,
  intent TEXT NOT NULL,
  weight REAL NOT NULL DEFAULT 1.0,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE form_corrections (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL,
  frase_norm TEXT NOT NULL,
  aula_id TEXT,
  ciclo_id TEXT,
  mod_cod TEXT,
  cat_id TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, nombre_item TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_usuarios_email ON usuarios(email);
CREATE INDEX idx_usuarios_google_id ON usuarios(google_id);
CREATE INDEX idx_usuarios_session_token ON usuarios(session_token);
CREATE UNIQUE INDEX ux_intent_learning_user_phrase_intent
ON intent_learning(user_id, phrase_norm, intent);
CREATE INDEX ix_intent_learning_user
ON intent_learning(user_id);
CREATE INDEX ix_intent_learning_intent
ON intent_learning(intent);
CREATE INDEX ix_intent_learning_updated_at
ON intent_learning(updated_at);
CREATE UNIQUE INDEX ux_form_corrections_user_frase
ON form_corrections(user_id, frase_norm);
CREATE INDEX ix_form_corrections_user
ON form_corrections(user_id);
